48	// RouterWarmupTask describes request-path state that should be materialized
49	// before the router reports ready. Readiness is explicit because some tasks
50	// depend on an embedding runtime that may be intentionally unavailable.
51	type RouterWarmupTask struct {
52		Name       string
53		Ready      bool
54		SkipReason string
55		Load       func() error
56	}
