75	func PrepareRouterRuntime(
76		ctx context.Context,
77		cfg *config.RouterConfig,
78		options PrepareRouterRuntimeOptions,
79	) (EmbeddingRuntimeState, error) {
80		component := options.Component
81		if component == "" {
82			component = "router"
83		}
84	
85		paths := resolveEmbeddingPaths(cfg)
86		state, embeddingTasks, tracker := embeddingRuntimeTasks(cfg, component, paths)
87		if !embeddingRuntimeConfigured(cfg, paths) {
88			logMissingEmbeddingModelsConfig(component)
89		}
90	
91		tasks := append([]Task{}, embeddingTasks...)
92		tasks = append(tasks, semanticCacheBERTTask(cfg, component)...)
93		tasks = append(tasks, vectorStoreBERTTask(cfg, component)...)
94		tasks = append(tasks, memoryBERTTask(cfg, component)...)
95		tasks = append(tasks, modalityClassifierTask(cfg, component, options.InitModalityClassifierFunc)...)
96		if len(tasks) == 0 {
97			return state, nil
98		}
99	
100		_, err := Execute(ctx, tasks, Options{
101			MaxParallelism: options.MaxParallelism,
102			OnEvent:        options.OnEvent,
103		})
104		if tracker != nil {
105			state = tracker.snapshot()
106		}
107		if embeddingRuntimeConfigured(cfg, paths) {
108			logging.ComponentEvent(component, "embedding_models_init_completed", map[string]interface{}{
109				"embedding_ready": state.AnyReady,
110				"tools_ready":     state.ToolsReady,
111				"tools_model":     cfg.EmbeddingConfig.ModelType,
112			})
113		}
114		return state, err
115	}
