173	func embeddingRuntimeTasks(
174		cfg *config.RouterConfig,
175		component string,
176		paths embeddingPaths,
177	) (EmbeddingRuntimeState, []Task, *embeddingStateTracker) {
178		if cfg.EmbeddingModels.UsesRemoteEmbeddingBackend() {
179			tracker := newEmbeddingStateTracker(EmbeddingRuntimeState{
180				EmbeddingProvider: remoteEmbeddingProviderRuntimeStateFromConfig(cfg),
181			})
182			logEmbeddingRuntimeStart(component, cfg, paths)
183			return tracker.snapshot(), remoteEmbeddingRuntimeTask(cfg, component, tracker), tracker
184		}
185		if !paths.hasConfiguredModels() {
186			return EmbeddingRuntimeState{}, nil, nil
187		}
188	
189		logEmbeddingRuntimeStart(component, cfg, paths)
190		requiresMultimodalTools := toolsUseMultiModalEmbeddings(cfg)
191		tracker := newEmbeddingStateTracker(EmbeddingRuntimeState{})
192		return tracker.snapshot(), buildEmbeddingRuntimeTasks(cfg, component, paths, requiresMultimodalTools, tracker), tracker
193	}
