205					"model_ref": bertModelID,
206					"use_cpu":   cfg.UseCPU,
207				})
208				if err := candle_binding.InitModel(bertModelID, cfg.UseCPU); err != nil {
209					logging.ComponentErrorEvent(component, "semantic_cache_bert_init_failed", map[string]interface{}{
