279	func modalityClassifierTask(
280		cfg *config.RouterConfig,
281		component string,
282		initFunc func(modelPath string, useCPU bool) error,
283	) []Task {
284		md := &cfg.ModalityDetector
285		if !md.Enabled {
286			return nil
287		}
288	
289		method := md.GetMethod()
290		if method != config.ModalityDetectionClassifier && method != config.ModalityDetectionHybrid {
291			return nil
292		}
293		if md.Classifier == nil || md.Classifier.ModelPath == "" {
294			return nil
295		}
296	
297		modelPath := config.ResolveModelPath(md.Classifier.ModelPath)
298		bestEffort := method == config.ModalityDetectionHybrid
299		return []Task{{
300			Name:       "router.modality.classifier",
301			BestEffort: bestEffort,
302			Run: func(context.Context) error {
303				logging.ComponentEvent(component, "modality_classifier_init_started", map[string]interface{}{
304					"method":    method,
305					"model_ref": modelPath,
306					"use_cpu":   md.Classifier.UseCPU,
307				})
308				if initFunc == nil {
309					return fmt.Errorf("modality classifier initializer is not configured")
310				}
311				if err := initFunc(modelPath, md.Classifier.UseCPU); err != nil {
312					event := map[string]interface{}{
313						"method":    method,
314						"model_ref": modelPath,
315						"error":     err.Error(),
316					}
317					if bestEffort {
318						event["fallback_to_keywords"] = true
319						logging.ComponentWarnEvent(component, "modality_classifier_init_failed", event)
320					} else {
321						logging.ComponentErrorEvent(component, "modality_classifier_init_failed", event)
322					}
323					return fmt.Errorf("failed to initialize modality classifier: %w", err)
324				}
325				logging.ComponentEvent(component, "modality_classifier_initialized", map[string]interface{}{
326					"method": method,
327				})
328				return nil
329			},
330		}}
331	}
