351	func initializeUnifiedEmbeddingModels(cfg *config.RouterConfig, component string, paths embeddingPaths) bool {
352		if !paths.hasUnifiedModels() {
353			return false
354		}
355	
356		semanticCacheNeedsBatched, mlSelectionNeedsBatched := batchedEmbeddingNeeds(cfg, paths.qwen3)
357		useBatched := semanticCacheNeedsBatched || mlSelectionNeedsBatched
358		logBatchedEmbeddingNeeds(component, semanticCacheNeedsBatched, mlSelectionNeedsBatched)
359		if err := initUnifiedEmbeddingModelFactory(cfg, paths, useBatched); err != nil {
360			logging.ComponentErrorEvent(component, "embedding_models_init_failed", map[string]interface{}{
361				"use_batched": useBatched,
362				"error":       err.Error(),
363			})
364			logging.ComponentWarnEvent(component, "embedding_runtime_degraded", map[string]interface{}{
365				"embedding_api_placeholder": true,
366				"tools_database_disabled":   true,
367			})
368			return false
369		}
370	
371		logging.ComponentEvent(component, "embedding_models_initialized", map[string]interface{}{
372			"use_batched": useBatched,
373		})
374		return true
375	}
376	
377	func batchedEmbeddingNeeds(cfg *config.RouterConfig, qwen3Path string) (bool, bool) {
378		semanticCacheNeedsBatched := cfg.Enabled &&
379			strings.ToLower(strings.TrimSpace(cfg.EmbeddingModel)) == "qwen3" &&
380			qwen3Path != ""
381		mlSelectionNeedsBatched := cfg.ModelSelection.Enabled &&
382			cfg.ModelSelection.ML.ModelsPath != "" &&
383			cfg.Qwen3ModelPath != ""
384		return semanticCacheNeedsBatched, mlSelectionNeedsBatched
385	}
