387	func logBatchedEmbeddingNeeds(component string, semanticCacheNeedsBatched bool, mlSelectionNeedsBatched bool) {
388		if !semanticCacheNeedsBatched && !mlSelectionNeedsBatched {
389			return
390		}
391		logging.ComponentDebugEvent(component, "batched_embedding_mode_required", map[string]interface{}{
392			"semantic_cache":  semanticCacheNeedsBatched,
393			"model_selection": mlSelectionNeedsBatched,
394		})
395	}
