487	func memoryConfigured(cfg *config.RouterConfig) bool {
488		if cfg.Memory.Enabled {
489			return true
490		}
491		for _, decision := range cfg.Decisions {
492			if decision.HasPlugin("memory") {
493				return true
494			}
