499	func resolveSemanticCacheEmbeddingModel(cfg *config.RouterConfig) string {
500		embeddingModel := strings.ToLower(strings.TrimSpace(cfg.EmbeddingModel))
501		if embeddingModel != "" {
502			return embeddingModel
503		}
504	
505		switch {
506		case cfg.MmBertModelPath != "":
507			return "mmbert"
508		case cfg.MultiModalModelPath != "":
509			return "multimodal"
510		case cfg.Qwen3ModelPath != "":
511			return "qwen3"
512		case cfg.GemmaModelPath != "":
513			return "gemma"
514		default:
515			return "bert"
516		}
517	}
