571	func cloneEmbeddingRuntimeState(state EmbeddingRuntimeState) EmbeddingRuntimeState {
572		state.EmbeddingProvider = cloneEmbeddingProviderRuntimeState(state.EmbeddingProvider)
573		return state
574	}
575	
576	func cloneEmbeddingProviderRuntimeState(status *EmbeddingProviderRuntimeState) *EmbeddingProviderRuntimeState {
577		if status == nil {
578			return nil
579		}
580		clone := *status
581		if status.APIKeyEnvSet != nil {
582			value := *status.APIKeyEnvSet
583			clone.APIKeyEnvSet = &value
584		}
585		if status.Healthy != nil {
586			value := *status.Healthy
587			clone.Healthy = &value
588		}
589		return &clone
590	}
591	
592	func remoteEmbeddingProviderRuntimeStateFromConfig(cfg *config.RouterConfig) *EmbeddingProviderRuntimeState {
593		if cfg == nil || !cfg.EmbeddingModels.UsesRemoteEmbeddingBackend() {
594			return nil
595		}
596	
597		apiKeyEnv := strings.TrimSpace(cfg.EmbeddingModels.Endpoint.APIKeyEnv)
598		var apiKeyEnvSet *bool
599		if apiKeyEnv != "" {
600			value := os.Getenv(apiKeyEnv) != ""
601			apiKeyEnvSet = &value
602		}
603	
604		dimension := cfg.EmbeddingModels.Endpoint.Dimensions
605		if dimension == 0 {
606			dimension = cfg.EmbeddingModels.EmbeddingConfig.TargetDimension
607		}
608	
609		return &EmbeddingProviderRuntimeState{
610			Mode:         "remote",
611			Backend:      cfg.EmbeddingModels.EmbeddingBackend(),
612			Model:        strings.TrimSpace(cfg.EmbeddingModels.Endpoint.Model),
613			Dimension:    dimension,
614			APIKeyEnv:    apiKeyEnv,
615			APIKeyEnvSet: apiKeyEnvSet,
616		}
617	}
618	
619	func remoteEmbeddingProviderProbeStatus(
620		cfg *config.RouterConfig,
621		provider embedding.Provider,
622		dimension int,
623		probeErr error,
624	) *EmbeddingProviderRuntimeState {
625		status := remoteEmbeddingProviderRuntimeStateFromConfig(cfg)
626		if status == nil {
627			status = &EmbeddingProviderRuntimeState{Mode: "remote"}
628		}
629		if provider != nil {
630			status.Backend = provider.Backend()
631		}
632		if dimension > 0 {
633			status.Dimension = dimension
634		}
635		healthy := probeErr == nil
636		status.Healthy = &healthy
637		status.LastCheckedAt = time.Now().UTC().Format(time.RFC3339)
638		if probeErr != nil {
639			status.LastProbeError = probeErr.Error()
640		}
641		return status
642	}
