644	func logEmbeddingRuntimeStart(component string, cfg *config.RouterConfig, paths embeddingPaths) {
645		logging.ComponentEvent(component, "embedding_models_init_started", map[string]interface{}{
646			"use_cpu":               cfg.UseCPU,
647			"backend":               cfg.EmbeddingModels.EmbeddingBackend(),
648			"qwen3_configured":      paths.qwen3 != "",
649			"gemma_configured":      paths.gemma != "",
650			"mmbert_configured":     paths.mmBert != "",
651			"multimodal_configured": paths.multiModal != "",
652			"bert_configured":       paths.bert != "",
653		})
654	}
655	
656	func embeddingRuntimeConfigured(cfg *config.RouterConfig, paths embeddingPaths) bool {
657		return cfg.EmbeddingModels.UsesRemoteEmbeddingBackend() || paths.hasConfiguredModels()
658	}
659	
660	func buildEmbeddingRuntimeTasks(
661		cfg *config.RouterConfig,
662		component string,
663		paths embeddingPaths,
664		requiresMultimodalTools bool,
665		tracker *embeddingStateTracker,
666	) []Task {
667		tasks := make([]Task, 0, 3)
668		tasks = append(tasks, unifiedEmbeddingRuntimeTask(cfg, component, paths, requiresMultimodalTools, tracker)...)
669		tasks = append(tasks, bertEmbeddingRuntimeTask(cfg, component, paths, tracker)...)
670		tasks = append(tasks, multiModalEmbeddingRuntimeTask(cfg, component, paths, requiresMultimodalTools, tracker)...)
671		return tasks
672	}
673	
674	func remoteEmbeddingRuntimeTask(
675		cfg *config.RouterConfig,
676		component string,
677		tracker *embeddingStateTracker,
678	) []Task {
679		return []Task{{
680			Name:       "router.embedding.remote_provider",
681			BestEffort: true,
682			Run: func(ctx context.Context) error {
683				logging.ComponentEvent(component, "remote_embedding_init_started", map[string]interface{}{
684					"backend": cfg.EmbeddingModels.EmbeddingBackend(),
685					"model":   cfg.EmbeddingModels.Endpoint.Model,
686				})
687				provider, err := embedding.NewProvider(cfg.EmbeddingModels, embedding.ProviderOptions{})
688				if err != nil {
689					tracker.markEmbeddingProvider(remoteEmbeddingProviderProbeStatus(cfg, nil, 0, err))
690					logging.ComponentErrorEvent(component, "remote_embedding_init_failed", map[string]interface{}{
691						"error": err.Error(),
692					})
693					return fmt.Errorf("failed to initialize remote embedding provider: %w", err)
694				}
695				embeddingVector, err := provider.Embed(ctx, "semantic router embedding probe")
696				if err != nil {
697					tracker.markEmbeddingProvider(remoteEmbeddingProviderProbeStatus(cfg, provider, 0, err))
698					logging.ComponentErrorEvent(component, "remote_embedding_init_failed", map[string]interface{}{
699						"backend": provider.Backend(),
700						"error":   err.Error(),
701					})
702					return fmt.Errorf("failed to probe remote embedding provider: %w", err)
703				}
704				tracker.markEmbeddingProvider(remoteEmbeddingProviderProbeStatus(cfg, provider, len(embeddingVector), nil))
705				logging.ComponentEvent(component, "remote_embedding_initialized", map[string]interface{}{
706					"backend":   provider.Backend(),
707					"dimension": len(embeddingVector),
708				})
709				tracker.markToolsReady()
710				return nil
711			},
712		}}
713	}
714	
715	func unifiedEmbeddingRuntimeTask(
716		cfg *config.RouterConfig,
717		component string,
718		paths embeddingPaths,
719		requiresMultimodalTools bool,
720		tracker *embeddingStateTracker,
721	) []Task {
722		if !paths.hasUnifiedModels() {
723			return nil
724		}
725	
726		return []Task{{
727			Name:       "router.embedding.unified_factory",
728			BestEffort: true,
729			Run: func(context.Context) error {
730				if !initializeUnifiedEmbeddingModels(cfg, component, paths) {
731					return fmt.Errorf("failed to initialize unified embedding models")
732				}
733				if requiresMultimodalTools {
734					tracker.markAnyReady()
735				} else {
736					tracker.markToolsReady()
737				}
738				return nil
739			},
740		}}
741	}
742	
743	func bertEmbeddingRuntimeTask(
744		cfg *config.RouterConfig,
745		component string,
746		paths embeddingPaths,
747		tracker *embeddingStateTracker,
748	) []Task {
749		if paths.bert == "" {
750			return nil
751		}
752	
753		return []Task{{
754			Name:       "router.embedding.bert",
755			BestEffort: true,
756			Run: func(context.Context) error {
757				if !initializeBERTModel(component, cfg.UseCPU, paths.bert, "memory_bert") {
758					return fmt.Errorf("failed to initialize bert embedding model")
759				}
760				tracker.markAnyReady()
761				return nil
762			},
763		}}
764	}
765	
766	func multiModalEmbeddingRuntimeTask(
767		cfg *config.RouterConfig,
768		component string,
769		paths embeddingPaths,
770		requiresMultimodalTools bool,
771		tracker *embeddingStateTracker,
772	) []Task {
773		if paths.multiModal == "" {
774			return nil
775		}
776	
777		return []Task{{
778			Name:       "router.embedding.multimodal",
779			BestEffort: true,
780			Run: func(context.Context) error {
781				if !initializeMultiModalEmbeddingModel(component, cfg.UseCPU, paths.multiModal) {
782					return fmt.Errorf("failed to initialize multimodal embedding model")
783				}
784				if requiresMultimodalTools {
785					tracker.markToolsReady()
786				} else {
787					tracker.markAnyReady()
788				}
789				return nil
790			},
791		}}
792	}
