1	package modelruntime
2	
3	import (
4		"context"
5		"fmt"
6		"runtime"
7		"runtime/debug"
8	
9		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
10	)
11	
12	type TaskStatus string
13	
14	const (
15		TaskPending   TaskStatus = "pending"
16		TaskRunning   TaskStatus = "running"
17		TaskSucceeded TaskStatus = "succeeded"
18		TaskFailed    TaskStatus = "failed"
19		TaskSkipped   TaskStatus = "skipped"
20	)
21	
22	type Task struct {
23		Name         string
24		Dependencies []string
25		BestEffort   bool
26		Run          func(context.Context) error
27	}
28	
29	type Event struct {
30		Task       string
31		Status     TaskStatus
32		BestEffort bool
33		Error      error
34	}
35	
36	type Options struct {
37		MaxParallelism int
38		OnEvent        func(Event)
39	}
40	
41	type TaskResult struct {
42		Name       string
43		Status     TaskStatus
44		BestEffort bool
45		Error      error
46	}
47	
48	type Summary struct {
49		Results map[string]TaskResult
50	}
51	
52	type taskState struct {
53		task          Task
54		remainingDeps int
55		dependents    []string
56		result        TaskResult
57	}
58	
59	type taskOutcome struct {
60		name string
61		err  error
62	}
63	
64	type executorRun struct {
65		states         map[string]*taskState
66		ready          []*taskState
67		resultCh       chan taskOutcome
68		emit           func(Event)
69		maxParallelism int
70		cancel         context.CancelFunc
71		running        int
72		finished       int
73		firstErr       error
74	}
75	
76	func DefaultParallelism(taskCount int) int {
77		if taskCount <= 1 {
78			return 1
79		}
80		if cpus := runtime.NumCPU(); cpus > 0 && cpus < taskCount {
81			return cpus
82		}
83		return taskCount
84	}
85	
86	func Execute(ctx context.Context, tasks []Task, options Options) (Summary, error) {
87		summary := Summary{Results: make(map[string]TaskResult, len(tasks))}
88		if len(tasks) == 0 {
89			return summary, nil
90		}
91	
92		states, err := buildTaskStates(tasks)
93		if err != nil {
94			return summary, err
95		}
96	
97		ready := initialReadyTasks(states)
98		if len(ready) == 0 {
99			return summary, fmt.Errorf("modelruntime: no runnable tasks; dependency graph is cyclic or invalid")
100		}
101	
102		runCtx, cancel := context.WithCancel(ctx)
103		defer cancel()
104	
105		run := newExecutorRun(states, ready, normalizeParallelism(len(tasks), options.MaxParallelism), cancel, len(tasks), options.OnEvent)
106		if err := run.execute(runCtx, len(tasks)); err != nil {
107			return summary, err
108		}
109	
110		for name, state := range states {
111			summary.Results[name] = state.result
112		}
113	
114		return summary, run.firstErr
115	}
116	
117	func newExecutorRun(
118		states map[string]*taskState,
119		ready []*taskState,
120		maxParallelism int,
121		cancel context.CancelFunc,
122		taskCount int,
123		onEvent func(Event),
124	) *executorRun {
125		return &executorRun{
126			states:         states,
127			ready:          ready,
128			resultCh:       make(chan taskOutcome, taskCount),
129			emit:           buildEventEmitter(onEvent),
130			maxParallelism: maxParallelism,
131			cancel:         cancel,
132		}
133	}
134	
135	func normalizeParallelism(taskCount int, maxParallelism int) int {
136		if maxParallelism <= 0 {
137			maxParallelism = DefaultParallelism(taskCount)
138		}
139		if maxParallelism > taskCount {
140			return taskCount
141		}
142		return maxParallelism
143	}
144	
145	func buildEventEmitter(onEvent func(Event)) func(Event) {
146		if onEvent == nil {
147			return func(Event) {}
148		}
149		return onEvent
150	}
151	
152	func (r *executorRun) execute(ctx context.Context, taskCount int) error {
153		for r.finished < taskCount {
154			r.scheduleReady(ctx)
155			done, err := r.handleIdleState()
156			if err != nil {
157				return err
158			}
159			if done {
160				return nil
161			}
162			r.handleOutcome(<-r.resultCh)
163		}
164		return nil
165	}
166	
167	func (r *executorRun) scheduleReady(ctx context.Context) {
168		for r.firstErr == nil && r.running < r.maxParallelism && len(r.ready) > 0 {
169			state := r.ready[0]
170			r.ready = r.ready[1:]
171			r.startTask(ctx, state)
172		}
173	}
174	
175	func (r *executorRun) handleIdleState() (bool, error) {
176		if r.running != 0 {
177			return false, nil
178		}
179		if r.firstErr != nil {
180			r.skipAllPending(r.firstErr)
181			return true, nil
182		}
183		if len(r.ready) == 0 {
184			return false, fmt.Errorf("modelruntime: unresolved task graph; dependency graph is cyclic or blocked")
185		}
186		return false, nil
187	}
188	
189	func (r *executorRun) skipAllPending(cause error) {
190		for name := range r.states {
191			r.markSkipped(name, cause)
192		}
193	}
194	
195	func (r *executorRun) markSkipped(name string, cause error) {
196		state := r.states[name]
197		if state == nil || state.result.Status != TaskPending {
198			return
199		}
200	
201		state.result.Status = TaskSkipped
202		state.result.Error = cause
203		r.finished++
204		r.emit(Event{
205			Task:       name,
206			Status:     TaskSkipped,
207			BestEffort: state.task.BestEffort,
208			Error:      cause,
209		})
210	
211		for _, dependent := range state.dependents {
212			r.markSkipped(dependent, fmt.Errorf("dependency %s did not complete: %w", name, cause))
213		}
214	}
215	
216	func (r *executorRun) startTask(ctx context.Context, state *taskState) {
217		state.result.Status = TaskRunning
218		r.running++
219		r.emit(Event{
220			Task:       state.task.Name,
221			Status:     TaskRunning,
222			BestEffort: state.task.BestEffort,
223		})
224	
225		go func(task Task) {
226			outcome := taskOutcome{name: task.Name}
227			// Initializers call into the Candle CGO bindings and re-run on every
228			// config reload, so an unrecovered panic here aborts a live router —
229			// even for BestEffort tasks, whose failures are meant to stay non-fatal.
230			// The send has to happen on both paths or execute() blocks on resultCh
231			// forever. Same intent as goSafely in pkg/extproc (#1843).
232			defer func() {
233				if rec := recover(); rec != nil {
234					outcome.err = fmt.Errorf("modelruntime: task %s panicked: %v", task.Name, rec)
235					logging.ComponentErrorEvent("modelruntime", "task_panic", map[string]interface{}{
236						"task":  task.Name,
237						"panic": rec,
238						"stack": string(debug.Stack()),
239					})
240				}
241				r.resultCh <- outcome
242			}()
243			outcome.err = task.Run(ctx)
244		}(state.task)
245	}
246	
247	func (r *executorRun) handleOutcome(outcome taskOutcome) {
248		state := r.states[outcome.name]
249		r.running--
250		if outcome.err != nil {
251			r.failTask(state, outcome.err)
252			return
253		}
254		r.succeedTask(state)
255	}
256	
257	func (r *executorRun) failTask(state *taskState, err error) {
258		state.result.Status = TaskFailed
259		state.result.Error = err
260		r.finished++
261		r.emit(Event{
262			Task:       state.task.Name,
263			Status:     TaskFailed,
264			BestEffort: state.task.BestEffort,
265			Error:      err,
266		})
267	
268		for _, dependent := range state.dependents {
269			r.markSkipped(dependent, fmt.Errorf("dependency %s failed: %w", state.task.Name, err))
270		}
271	
272		if state.task.BestEffort || r.firstErr != nil {
273			return
274		}
275		r.firstErr = fmt.Errorf("task %s failed: %w", state.task.Name, err)
276		r.cancel()
277	}
278	
279	func (r *executorRun) succeedTask(state *taskState) {
280		state.result.Status = TaskSucceeded
281		r.finished++
282		r.emit(Event{
283			Task:       state.task.Name,
284			Status:     TaskSucceeded,
285			BestEffort: state.task.BestEffort,
286		})
287	
288		if r.firstErr != nil {
289			return
290		}
291		r.enqueueDependents(state)
292	}
293	
294	func (r *executorRun) enqueueDependents(state *taskState) {
295		for _, dependentName := range state.dependents {
296			dependent := r.states[dependentName]
297			if dependent == nil || dependent.result.Status != TaskPending {
298				continue
299			}
300			dependent.remainingDeps--
301			if dependent.remainingDeps == 0 {
302				r.ready = append(r.ready, dependent)
303			}
304		}
305	}
306	
307	func buildTaskStates(tasks []Task) (map[string]*taskState, error) {
308		states := make(map[string]*taskState, len(tasks))
309		for _, task := range tasks {
310			if task.Name == "" {
311				return nil, fmt.Errorf("modelruntime: task name cannot be empty")
312			}
313			if task.Run == nil {
314				return nil, fmt.Errorf("modelruntime: task %s has nil Run function", task.Name)
315			}
316			if _, exists := states[task.Name]; exists {
317				return nil, fmt.Errorf("modelruntime: duplicate task name %s", task.Name)
318			}
319			states[task.Name] = &taskState{
320				task: task,
321				result: TaskResult{
322					Name:       task.Name,
323					Status:     TaskPending,
324					BestEffort: task.BestEffort,
325				},
326			}
327		}
328	
329		for _, task := range tasks {
330			state := states[task.Name]
331			for _, dependency := range task.Dependencies {
332				dependencyState := states[dependency]
333				if dependencyState == nil {
334					return nil, fmt.Errorf("modelruntime: task %s depends on unknown task %s", task.Name, dependency)
335				}
336				state.remainingDeps++
337				dependencyState.dependents = append(dependencyState.dependents, task.Name)
338			}
339		}
340	
341		return states, nil
342	}
343	
344	func initialReadyTasks(states map[string]*taskState) []*taskState {
345		ready := make([]*taskState, 0, len(states))
346		for _, state := range states {
347			if state.remainingDeps == 0 {
348				ready = append(ready, state)
349			}
350		}
351		return ready
352	}
